/* @layer shared-asset-extraction @kind logic */
import type { ImportContext } from '../pipeline/import-context.type';
import { peek, recipeState } from './ctgen/require-tools';
import { hx } from './ctgen/text-file';

/** menu_audit_cmp.py itemuse: X@4, R@50, A@80, Down@110, A@130, A@150, A@170; peeked at 172 + 2. */
const DRIVE = '0:4,200:2,0:44,80:2,0:28,100:2,0:28,20:2,0:18,100:2,0:18,100:2,0:18,100:2,0:2';
const BASE = 0x6000 * 2;

const HEADER = [
  '// menu_itemoverlay.h -- GENERATED by tools/_gen_item_overlay.py from the oracle VRAM of the Item target overlay.',
  "// The BG2 cells of $FF:C0A6's `04 8B 03 02 20 0E 10` window (style 8B, attribute 03, at (2,32), 14 x 16);",
  "// C2/AFB5's offset-per-tile rows show them at screen columns 16-28, lines 80-207 (menu.c).",
  '#ifndef CT_MENU_ITEMOVERLAY_H',
  '#define CT_MENU_ITEMOVERLAY_H',
  '#include <stdint.h>',
  'static const uint16_t ctItemOverlayWinTM[16][14] = {',
];

/** tools/gen/menu_itemoverlay.py: the Item screen's target-select window cells (recipe grupo_3_mapa, the itemuse drive). */
const genMenuItemoverlay = async (ctx: ImportContext): Promise<string> => {
  const { vram } = await peek(ctx, await recipeState(ctx, 'grupo_3_mapa'), DRIVE);
  const lines = [...HEADER];
  for (let r = 32; r < 48; r += 1) {
    const row: string[] = [];
    for (let c = 2; c < 16; c += 1) {
      const o = BASE + (r * 32 + c) * 2;
      const w = (vram[o] as number) | ((vram[o + 1] as number) << 8);
      const tile = w & 0x3ff;
      if (tile < 0x3dc || tile > 0x3ef) {
        throw new Error(`menu_itemoverlay: not a window tile at (${c},${r}): ${hx(w, 4)} -- the overlay is not up`);
      }
      row.push(`0x${hx(w, 4)}`);
    }
    lines.push(`  { ${row.join(', ')} },`);
  }
  lines.push('};', '#endif', '');
  return lines.join('\n');
};

export { genMenuItemoverlay };
